/**
 * Kumva Trigger Node with Scheduling
 * Initiates campaigns via schedule (cron, interval, once) or manual trigger
 */

module.exports = function(RED) {
  const csv = require('csvtojson');
  const schedule = require('node-schedule');
  const helpers = require('kumva-insights/utils/helpers');
  const DataStorage = require('kumva-insights/utils/data-storage');

  // ============================================================
  // Shared registry of every deployed Trigger node, keyed by flow id.
  // Backs the two global HTTP endpoints below (list flows / start by id).
  // ============================================================
  function getTriggerRegistry(node) {
    let registry = node.context().global.get('kumvaTriggerRegistry');
    if (!registry) {
      registry = new Map();
      node.context().global.set('kumvaTriggerRegistry', registry);
    }
    return registry;
  }

  function getFlowLabel(flowId, fallback) {
    try {
      const flowsConfig = RED.nodes.getFlows();
      const tab = (flowsConfig?.flows || []).find(n => n.id === flowId && n.type === 'tab');
      return (tab && tab.label) || fallback;
    } catch (e) {
      return fallback;
    }
  }

  function registerGlobalFlowEndpoints() {
    // Guard against re-registering these routes every time a Trigger node
    // is instantiated (one per deploy, potentially many Trigger nodes).
    if (RED.httpAdmin._kumvaFlowEndpointsRegistered) return;
    RED.httpAdmin._kumvaFlowEndpointsRegistered = true;

    /**
     * GET /kumva/flows
     * Lists every deployed flow that has a Kumva Trigger node on it.
     * Response: { success: true, flows: [{ flowId, name }, ...] }
     * `flowId` is exactly what you pass to POST /kumva/flows/:flowId/start
     */
    RED.httpAdmin.get('/kumva/flows', (req, res) => {
      try {
        const flows = Array.from((global.__kumvaTriggerRegistry || new Map()).entries()).map(([flowId, entry]) => ({
          flowId,
          name: getFlowLabel(flowId, entry.name) || entry.name || 'Untitled Flow'
        }));
        res.json({ success: true, flows });
      } catch (error) {
        res.status(500).json({ success: false, error: error.message });
      }
    });

    /**
     * POST /kumva/flows/:flowId/start
     * Body: the contacts array itself - the exact same shape as the node's
     * own "JSON Data" contact source, e.g.:
     *   [{ "phone": "+250788123456", "name": "John" }, { "phone": "+250788999999", "name": "Alice" }]
     * A body wrapped as { "contacts": [...] } is also accepted for convenience.
     * Starts the campaign on the Trigger node living on that flow, using
     * these posted contacts instead of whatever is configured on the node.
     */
    RED.httpAdmin.post('/kumva/flows/:flowId/start', async (req, res) => {
      try {
        const { flowId } = req.params;
        const registry = global.__kumvaTriggerRegistry || new Map();
        const entry = registry.get(flowId);

        if (!entry) {
          return res.status(404).json({ success: false, error: `No Kumva Trigger node found for flow "${flowId}"` });
        }

        let body = req.body;

        // Allow the raw body to arrive as a JSON string (some HTTP clients send it that way).
        if (typeof body === 'string') {
          try { body = JSON.parse(body); } catch (e) { body = null; }
        }

        // Accept either the contacts array directly, or wrapped as { contacts: [...] }.
        let contacts;
        if (Array.isArray(body)) {
          contacts = body;
        } else if (body && Array.isArray(body.contacts)) {
          contacts = body.contacts;
        }

        if (!Array.isArray(contacts)) {
          return res.status(400).json({
            success: false,
            error: 'Request body must be a JSON array of contacts (same shape as the node\'s "JSON Data" source), e.g. [{"phone":"+250788123456","name":"John"}]'
          });
        }

        const result = await entry.start(contacts);
        if (!result.success) {
          return res.status(409).json({ success: false, error: result.error, flowId });
        }

        return res.json({ success: true, flowId, campaignId: result.campaignId, contactCount: result.contactCount });
      } catch (error) {
        res.status(500).json({ success: false, error: error.message });
      }
    });
  }

  function KumvaTriggerNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const flowId = node.z;
    const flowContext = node.context().flow;
    const globalContext = node.context().global;

    const storage = new DataStorage();
    let campaignId = null;
    let contacts = [];
    let currentIndex = 0;
    let triggerInterval = null;
    let campaignRunning = false;
    let scheduleJob = null;

    /**
     * Parses the phone numbers from the method and list provided, or from an
     * explicit override (e.g. contacts posted to /kumva/flows/:flowId/start).
     * @param {Array} [contactsOverride] - Array of contact objects to use instead of the configured source
     * @returns Whether we extracted any valid phone numbers from the list and methods available
     */
    async function parseContacts(contactsOverride) {
      try {
        if (Array.isArray(contactsOverride)) {
          contacts = contactsOverride;
        } else {
          const source = config.contactSource;
          contacts = [];
          switch (source) {
            case 'csv':
              if (!config.csvData || config.csvData.trim() === '') return false;
              contacts = await csv().fromString(config.csvData);
              break;
            case 'json':
              contacts = helpers.safeJsonParse(config.jsonData, []);
              if (!Array.isArray(contacts)) contacts = [];
              break;
            case 'manual':
              contacts = (config.manualContacts || '')
                .split('\n')
                .map(phone => phone.trim())
                .filter(Boolean)
                .map(phone => ({ [config.phoneColumn || 'phone']: phone }));
              break;
            default:
              // include a default case to handle json data from http request from other external sources.
              return false;
          }
        }

        contacts = contacts.filter(contact => {
          const phone = contact[config.phoneColumn || 'phone'];
          return phone && helpers.isValidPhoneNumber(phone);
        });

        return contacts.length > 0;
      } catch (error) {
        node.error(`Parse contacts error: ${error.message}`);
        return false;
      }
    }

    /**
     * Processes a batch of contacts and passes each one individual contact details to the next node.(usually sendMessage)
     * @returns void
     */
    function processNextContact() {
      if (currentIndex >= contacts.length) {
        completeCampaign();
        return;
      }

      const contact = contacts[currentIndex];
      currentIndex += 1;
      const phoneNumber = contact[config.phoneColumn || 'phone'];
      const initialMessage = helpers.resolveVariables(config.initialMessage || '', contact);

      const msg = {
        phoneNumber,
        contactData: contact,
        campaignId,
        initialMessage,
        payload: initialMessage,
        _kumva: {
          campaignId,
          contactIndex: currentIndex - 1,
          totalContacts: contacts.length
        }
      };

      if (config.additionalFields) {
        config.additionalFields.split(',').map(field => field.trim()).filter(Boolean).forEach(field => {
          if (contact[field] !== undefined) {
            msg[field] = contact[field];
          }
        });
      }

      flowContext.set('kumvaLastContact', contact);
      flowContext.set('kumvaLastPhoneNumber', phoneNumber);
      flowContext.set('kumvaLastCampaignId', campaignId);
      globalContext.set('kumvaLastContact', contact);
      globalContext.set('kumvaLastPhoneNumber', phoneNumber);
      globalContext.set('kumvaLastCampaignId', campaignId);

      // send the current contact details to the next node in the flow
      node.send(msg);
      // update the status of the node to show progress
      node.status({ fill: 'blue', shape: 'dot', text: `Processing ${currentIndex}/${contacts.length}` });
    }

    function completeCampaign() {
      if (triggerInterval) {
        clearInterval(triggerInterval);
        triggerInterval = null;
      }
      campaignRunning = false;

      // initiate a campaign storage in the storage section (local JSON file at the moment and db later.)
      storage.saveCampaign(campaignId, {
        name: config.name,
        totalContacts: contacts.length,
        completedAt: new Date().toISOString(),
        status: 'completed'
      });

      node.status({ fill: 'green', shape: 'dot', text: `Complete (${contacts.length} contacts)` });
    }

    /**
     * @param {Array} [contactsOverride] - Optional explicit contacts (bypasses configured contact source)
     * @returns {Promise<{success: boolean, error?: string, campaignId?: string, contactCount?: number}>}
     */
    async function startCampaign(contactsOverride) {
      try {
        if (campaignRunning) {
          node.warn('Campaign already running');
          return { success: false, error: 'Campaign already running' };
        }

        const parsed = await parseContacts(contactsOverride);
        if (!parsed) {
          node.error('No valid contacts found');
          node.status({ fill: 'red', shape: 'dot', text: 'No valid contacts' });
          return { success: false, error: 'No valid contacts found' };
        }

        campaignId = `campaign_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        campaignRunning = true;
        currentIndex = 0;

        storage.saveCampaign(campaignId, {
          name: config.name,
          totalContacts: contacts.length,
          startedAt: new Date().toISOString(),
          status: 'running'
        });

        node.status({ fill: 'blue', shape: 'dot', text: `Starting (${contacts.length} contacts)` });

        const rateLimit = config.rateLimit || 60;
        const intervalMs = 60000 / rateLimit;

        triggerInterval = setInterval(() => {
          processNextContact();
        }, intervalMs);

        processNextContact();

        return { success: true, campaignId, contactCount: contacts.length };
      } catch (error) {
        node.error(`Campaign error: ${error.message}`);
        node.status({ fill: 'red', shape: 'dot', text: 'Error' });
        return { success: false, error: error.message };
      }
    }

    function setupSchedule() {
      if (config.scheduleType === 'none') return;

      try {
        if (config.scheduleType === 'cron') {
          scheduleJob = schedule.scheduleJob(config.cronExpression, startCampaign);
          node.log(`Scheduled: ${config.cronExpression}`);
        } else if (config.scheduleType === 'interval') {
          const intervalMs = helpers.getTimeoutMs(config.intervalTime);
          scheduleJob = setInterval(startCampaign, intervalMs);
          node.log(`Scheduled: every ${config.intervalTime}`);
        } else if (config.scheduleType === 'once') {
          const delayMs = helpers.getTimeoutMs(config.delayTime);
          scheduleJob = setTimeout(startCampaign, delayMs);
          node.log(`Scheduled: in ${config.delayTime}`);
        }
      } catch (error) {
        node.error(`Schedule setup error: ${error.message}`);
      }
    }

    node.on('input', function(msg) {
      if (msg.payload === 'start' || msg.trigger === true) {
        startCampaign();
      } else if (msg.payload === 'stop' || msg.trigger === false) {
        if (triggerInterval) {
          clearInterval(triggerInterval);
          triggerInterval = null;
        }
        campaignRunning = false;
        node.status({ fill: 'orange', shape: 'dot', text: 'Stopped' });
      }
    });

    setupSchedule();

    RED.httpAdmin.post(`/kumva/trigger/${node.id}/start`, (req, res) => {
      startCampaign();
      res.json({ success: true });
    });

    RED.httpAdmin.post(`/kumva/trigger/${node.id}/stop`, (req, res) => {
      if (triggerInterval) {
        clearInterval(triggerInterval);
        triggerInterval = null;
      }
      campaignRunning = false;
      node.status({ fill: 'orange', shape: 'dot', text: 'Stopped' });
      res.json({ success: true });
    });

    // Register this node in the shared flow registry so the global
    // /kumva/flows and /kumva/flows/:flowId/start endpoints can find it.
    if (!global.__kumvaTriggerRegistry) {
      global.__kumvaTriggerRegistry = new Map();
    }
    global.__kumvaTriggerRegistry.set(flowId, {
      nodeId: node.id,
      name: config.name || 'Trigger',
      start: startCampaign
    });
    registerGlobalFlowEndpoints();

    node.on('close', function() {
      if (triggerInterval) clearInterval(triggerInterval);
      if (scheduleJob) {
        if (scheduleJob.cancel) scheduleJob.cancel();
        else clearTimeout(scheduleJob);
      }
      campaignRunning = false;

      if (global.__kumvaTriggerRegistry) {
        global.__kumvaTriggerRegistry.delete(flowId);
      }
    });

    node.status({ fill: 'yellow', shape: 'ring', text: 'Ready to trigger' });
  }

  RED.nodes.registerType('kumva-trigger', KumvaTriggerNode);
};